import json
import urllib.request
import urllib.parse

# Connect to Chrome DevTools Protocol
def cdp_send(command, params=None):
    if params is None:
        params = {}
    payload = json.dumps({"method": command, "params": params}).encode()
    req = urllib.request.Request("http://localhost:9222/devtools/page/executeCommand", data=payload)
    req.add_header("Content-Type", "application/json")
    try:
        with urllib.request.urlopen(req, timeout=5) as resp:
            return json.loads(resp.read())
    except Exception as e:
        print(f"CDP error: {e}")
        return None

# Get all pages/tabs
result = cdp_send("Target.getTargets")
if result and "targetInfos" in result:
    for target in result["targetInfos"]:
        if target.get("type") == "page":
            print(f"Page: {target.get('title', 'N/A')} | URL: {target.get('url', 'N/A')} | ID: {target['id']}")

# Let's try to evaluate JavaScript on the first page we find
for target in result.get("targetInfos", []):
    if target.get("type") == "page":
        page_id = target["id"]
        # Get current URL
        url_result = cdp_send("Target.createTarget", {"url": f"devtools://devtools/bundled/inspector.html?ws=localhost:9222/devtools/page/{page_id}"})
        print(f"Page ID: {page_id}")

        # Execute JS to get page content info
        js_result = cdp_send("Runtime.evaluate", {
            "expression": "document.title + ' | ' + window.location.href",
            "returnByValue": True
        })
        print(f"JS result: {js_result}")
        break
